param([Parameter(Mandatory=$true)][string]$InputJson,[string]$OutputDir="")\n$ErrorActionPreference="Stop"\n$Repo=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path\nif(-not $OutputDir){$p=Get-Content $InputJson -Raw|ConvertFrom-Json;$id=([string]$p.project_id)-replace '[^A-Za-z0-9_.-]','_';$OutputDir=Join-Path $Repo "outputs\\runtime\\tropical_residential_design_engine_v1_0\\$id"}\n$py=Get-Command python -ErrorAction SilentlyContinue;if(-not $py){throw "Python required; Phoenix will not install it automatically."}\nPush-Location $Repo;try{& $py.Source -m phoenix.design.tropical_residential.cli --input $InputJson --output $OutputDir;if($LASTEXITCODE -ne 0){throw "TRDE failed: $LASTEXITCODE"}}finally{Pop-Location}\n